#include <iostream>

// Worker functions: each dedicated to a single, well-defined task
int computeSquare(int value) {
    return value * value;
}

int computeSumOfSquares(int a, int b) {
    // computeSumOfSquares acts as a boss delegating work to computeSquare
    return computeSquare(a) + computeSquare(b);
}

int main() {
    int num1 = 3;
    int num2 = 4;

    // main acts as the top-level boss invoking computeSumOfSquares
    int result = computeSumOfSquares(num1, num2);

    std::cout << "Sum of squares: " << result << "\n";
    return 0;
}

